    /// <summary>Une cellule TEXTE retypée selon le type DÉCLARÉ ; inchangée si elle ne s'y prête pas.</summary>
    public static JsonNode? CoerceCell(JsonNode? value, IReadOnlyList<string> declared)
    {
        ArgumentNullException.ThrowIfNull(declared);
        if (value is not JsonValue cell || cell.GetValueKind() != JsonValueKind.String)
        {
            return value?.DeepClone();
        }

        var text = cell.GetValue<string>().Trim();
        if (text.Length == 0)
        {
            return null;
        }

        if (declared.Contains("boolean") && Booleans.TryGetValue(text, out var flag))
        {
            return JsonValue.Create(flag);
        }

        if (declared.Contains("integer") && IntPattern.IsMatch(text) && long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var integer))
        {
            return JsonValue.Create(integer);
        }

        if (declared.Contains("number") && FloatPattern.IsMatch(text) && double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out var number))
        {
            return JsonValue.Create(number);
        }

        return cell.DeepClone();
    }

    /// <summary>La valeur est-elle d'un des types déclarés ? Un entier EST un nombre ; un booléen n'est pas un entier.</summary>
    public static bool TypeOk(JsonNode? value, IReadOnlyList<string> declared)
    {
