        if (RecordValues.IsNull(value))
        {
            return declared.Count == 0 || declared.Contains("null");
        }

        var actual = RecordValues.SchemaType(value);
        return declared.Count == 0
            || declared.Contains(actual)
            || (actual == "integer" && declared.Contains("number"));
    }
